3	import { useState } from 'react'
4	import { parsePhoneNumber, isValidPhoneNumber, getCountries, getCountryCallingCode } from 'libphonenumber-js'
5	import type { CountryCode } from 'libphonenumber-js'
6	import { cn } from '@/lib/utils'
7	import { ComboBox } from '@/components/ui/combobox'
8	import { Input } from '@/components/ui/input'
9	
10	interface PhoneInputProps {
11	  value: string
12	  onValueChange: (value: string) => void
13	  defaultCountry?: CountryCode
14	  placeholder?: string
15	  disabled?: boolean
16	  className?: string
17	}
18	
19	// Build sorted country list (all ISO 3166-1 alpha-2 with calling codes)
20	function buildCountryOptions() {
21	  return getCountries()
22	    .map((code) => {
23	      try {
24	        const calling = getCountryCallingCode(code)
25	        return {
26	          value: code,
27	          label: `${code} +${calling}`,
28	          description: `+${calling}`,
29	        }
30	      } catch {
31	        return null
32	      }
33	    })
34	    .filter((c): c is NonNullable<typeof c> => c !== null)
35	    .sort((a, b) => a.value.localeCompare(b.value))
36	}
37	
38	const countryOptions = buildCountryOptions()
39	
40	function getFlag(countryCode: string): string {
41	  // Use regional indicator symbols to render flag emoji
42	  return countryCode
43	    .toUpperCase()
44	    .split('')
45	    .map((c) => String.fromCodePoint(0x1f1e6 + c.charCodeAt(0) - 65))
46	    .join('')
47	}
48	
49	export function PhoneInput({
50	  value,
51	  onValueChange,
52	  defaultCountry = 'US',
53	  placeholder = 'Phone number',
54	  disabled = false,
55	  className,
56	}: PhoneInputProps) {
57	  const [country, setCountry] = useState<CountryCode>(defaultCountry)
58	
59	  // Parse out local number from E.164 value if present
60	  function getLocalNumber(): string {
61	    if (!value) return ''
62	    try {
63	      const parsed = parsePhoneNumber(value, country)
64	      if (parsed) return parsed.formatNational()
65	    } catch {
66	      // not a full E.164 yet
67	    }
68	    return value
69	  }
70	
71	  function handleLocalChange(e: React.ChangeEvent<HTMLInputElement>) {
72	    const local = e.target.value
73	    if (!local) {
74	      onValueChange('')
75	      return
76	    }
77	    try {
78	      const calling = getCountryCallingCode(country)
79	      const full = `+${calling}${local.replace(/\D/g, '')}`
80	      if (isValidPhoneNumber(full, country)) {
81	        const parsed = parsePhoneNumber(full, country)
82	        onValueChange(parsed.format('E.164'))
83	      } else {
84	        onValueChange(full)
85	      }
86	    } catch {
87	      onValueChange(local)
88	    }
89	  }
90	
91	  function handleCountryChange(val: string | null) {
92	    if (val) setCountry(val as CountryCode)
93	  }
94	
95	  const flag = getFlag(country)
96	  let callingCode = ''
97	  try {
98	    callingCode = `+${getCountryCallingCode(country)}`
99	  } catch {
100	    callingCode = ''
101	  }
102	
103	  return (
104	    <div
105	      className={cn(
106	        'flex items-center rounded-md border border-input bg-background focus-within:ring-2 focus-within:ring-ring transition-shadow',
107	        disabled && 'opacity-50 cursor-not-allowed',
108	        className,
109	      )}
110	    >
111	      {/* Country selector */}
112	      <div className="shrink-0 border-r border-input">
113	        <ComboBox
114	          options={countryOptions}
115	          value={country}
116	          onValueChange={handleCountryChange}
117	          placeholder={`${flag} ${callingCode}`}
118	          searchPlaceholder="Search country..."
119	          disabled={disabled}
120	          className="h-9 border-0 rounded-r-none rounded-l-md shadow-none focus:ring-0 w-28 gap-1"
121	        />
122	      </div>
123	
124	      {/* Number input */}
125	      <Input
126	        type="tel"
127	        value={getLocalNumber()}
128	        onChange={handleLocalChange}
129	        placeholder={placeholder}
130	        disabled={disabled}
131	        className="border-0 rounded-l-none shadow-none focus-visible:ring-0 flex-1"
132	      />
133	    </div>
134	  )
135	}
