6	interface MoneyInputProps {
7	  value: number | undefined         // value in cents (integer)
8	  onValueChange: (cents: number | undefined) => void
9	  currency?: string                  // ISO 4217, default: 'USD'
10	  locale?: string                    // default: 'en-US'
11	  placeholder?: string
12	  disabled?: boolean
13	  className?: string
14	}
15	
16	function getCurrencySymbol(currency: string, locale: string): string {
17	  try {
18	    return new Intl.NumberFormat(locale, { style: 'currency', currency, currencyDisplay: 'symbol' })
19	      .formatToParts(0)
20	      .find((p) => p.type === 'currency')?.value ?? currency
21	  } catch {
22	    return currency
23	  }
24	}
25	
26	function centsToDisplay(cents: number | undefined, precision: number): string {
27	  if (cents === undefined) return ''
28	  return (cents / Math.pow(10, precision)).toFixed(precision)
29	}
30	
31	function displayToCents(display: string, precision: number): number | undefined {
32	  const n = parseFloat(display.replace(/,/g, ''))
33	  if (isNaN(n)) return undefined
34	  return Math.round(n * Math.pow(10, precision))
35	}
36	
37	export function MoneyInput({
38	  value,
39	  onValueChange,
40	  currency = 'USD',
41	  locale = 'en-US',
42	  placeholder = '0.00',
43	  disabled = false,
44	  className,
45	}: MoneyInputProps) {
46	  const precision = 2
47	  const symbol = getCurrencySymbol(currency, locale)
48	  const [display, setDisplay] = useState<string>(centsToDisplay(value, precision) ?? '')
49	  const inputRef = useRef<HTMLInputElement>(null)
50	
51	  function handleChange(e: React.ChangeEvent<HTMLInputElement>) {
52	    const raw = e.target.value
53	    // Allow only digits, decimal point, minus
54	    if (/^-?\d*\.?\d*$/.test(raw) || raw === '') {
55	      setDisplay(raw)
56	      onValueChange(displayToCents(raw, precision))
57	    }
58	  }
59	
60	  function handleBlur() {
61	    if (display !== '') {
62	      const cents = displayToCents(display, precision)
63	      if (cents !== undefined) {
64	        setDisplay(centsToDisplay(cents, precision) ?? '')
65	      }
66	    }
67	  }
68	
69	  return (
70	    <div
71	      className={cn(
72	        'flex items-center rounded-md border border-input bg-background focus-within:ring-2 focus-within:ring-ring transition-shadow',
73	        disabled && 'opacity-50 cursor-not-allowed',
74	        className,
75	      )}
76	      onClick={() => inputRef.current?.focus()}
77	    >
78	      {/* Currency symbol prefix */}
79	      <div className="flex items-center px-3 border-r border-input bg-muted/30 rounded-l-md self-stretch">
80	        <span className="text-sm text-muted-foreground tabular-nums select-none">
81	          {symbol}
82	        </span>
83	      </div>
84	
85	      {/* Number input */}
86	      <input
87	        ref={inputRef}
88	        type="text"
89	        inputMode="decimal"
90	        value={display}
91	        onChange={handleChange}
92	        onBlur={handleBlur}
93	        placeholder={placeholder}
94	        disabled={disabled}
95	        className="flex-1 bg-transparent px-3 py-2 text-sm tabular-nums outline-none placeholder:text-muted-foreground disabled:cursor-not-allowed"
96	      />
97	    </div>
98	  )
99	}
