7	interface NumberInputProps {
8	  value: number | undefined
9	  onValueChange: (value: number | undefined) => void
10	  min?: number
11	  max?: number
12	  step?: number
13	  precision?: number
14	  placeholder?: string
15	  disabled?: boolean
16	  className?: string
17	}
18	
19	export function NumberInput({
20	  value,
21	  onValueChange,
22	  min,
23	  max,
24	  step = 1,
25	  precision = 0,
26	  placeholder,
27	  disabled = false,
28	  className,
29	}: NumberInputProps) {
30	  const inputRef = useRef<HTMLInputElement>(null)
31	
32	  function clamp(n: number): number {
33	    let result = n
34	    if (min !== undefined) result = Math.max(min, result)
35	    if (max !== undefined) result = Math.min(max, result)
36	    return parseFloat(result.toFixed(precision))
37	  }
38	
39	  function handleDecrement() {
40	    const next = clamp((value ?? 0) - step)
41	    onValueChange(next)
42	  }
43	
44	  function handleIncrement() {
45	    const next = clamp((value ?? 0) + step)
46	    onValueChange(next)
47	  }
48	
49	  function handleChange(e: React.ChangeEvent<HTMLInputElement>) {
50	    const raw = e.target.value
51	    if (raw === '' || raw === '-') {
52	      onValueChange(undefined)
53	      return
54	    }
55	    const n = parseFloat(raw)
56	    if (!isNaN(n)) {
57	      onValueChange(clamp(n))
58	    }
59	  }
60	
61	  function handleKeyDown(e: React.KeyboardEvent<HTMLInputElement>) {
62	    if (e.key === 'ArrowUp') {
63	      e.preventDefault()
64	      handleIncrement()
65	    } else if (e.key === 'ArrowDown') {
66	      e.preventDefault()
67	      handleDecrement()
68	    }
69	  }
70	
71	  const atMin = min !== undefined && value !== undefined && value <= min
72	  const atMax = max !== undefined && value !== undefined && value >= max
73	
74	  return (
75	    <div
76	      className={cn(
77	        'flex items-center rounded-md border border-input bg-background focus-within:ring-2 focus-within:ring-ring focus-within:ring-offset-0 transition-shadow',
78	        disabled && 'opacity-50 cursor-not-allowed',
79	        className,
80	      )}
81	    >
82	      <input
83	        ref={inputRef}
84	        type="number"
85	        value={value ?? ''}
86	        onChange={handleChange}
87	        onKeyDown={handleKeyDown}
88	        placeholder={placeholder}
89	        disabled={disabled}
90	        min={min}
91	        max={max}
92	        step={step}
93	        className="flex-1 bg-transparent px-3 py-2 text-sm tabular-nums outline-none placeholder:text-muted-foreground disabled:cursor-not-allowed [appearance:textfield] [&::-webkit-outer-spin-button]:appearance-none [&::-webkit-inner-spin-button]:appearance-none"
94	      />
95	      <div className="flex flex-col border-l border-input shrink-0">
96	        <button
97	          type="button"
98	          onClick={handleIncrement}
99	          disabled={disabled || atMax}
100	          className="flex h-5 w-8 items-center justify-center text-muted-foreground hover:text-foreground hover:bg-muted/50 transition-colors disabled:opacity-40 disabled:cursor-not-allowed"
101	          aria-label="Increment"
102	          tabIndex={-1}
103	        >
104	          <Plus className="size-3" />
105	        </button>
106	        <button
107	          type="button"
108	          onClick={handleDecrement}
109	          disabled={disabled || atMin}
110	          className="flex h-5 w-8 items-center justify-center border-t border-input text-muted-foreground hover:text-foreground hover:bg-muted/50 transition-colors disabled:opacity-40 disabled:cursor-not-allowed"
111	          aria-label="Decrement"
112	          tabIndex={-1}
113	        >
114	          <Minus className="size-3" />
115	        </button>
116	      </div>
117	    </div>
118	  )
119	}
